import math
# (b) re-derivation: leak vs fees for stakes actually generated by K0, turnover tau/day
Er=5.01e-4; a=.52; L=10; fs=0.00092
for K0,tau in [(0.01,10),(0.10,10),(0.5,10),(0.5,45)]:
    F=K0*tau*fs
    # exposure actually generated: staked share per round = tau/576 of K0 ; net notional = b*K0*tau/576*L per round, b=1 worst
    net_per_round=K0*tau/576*L
    leak=(2*a-1)*Er*net_per_round*576   # per day, BTC-like
    print(f"K0={K0} tau={tau}: F={F*100:.4f}%T/day, leak actually generated (b=1,L=10) {leak*100:.4f}%T/day, F/leak={F/leak:.2f}; notional per round {net_per_round*100:.3f}%T vs limit-sum 521.9% T(per side in T units 5.219)")
# what the (b)-rule allows in net notional per round: F/((2a-1)*Er*576)
for K0,tau in [(0.01,10),(0.10,10),(0.5,10)]:
    F=K0*tau*fs; allowed=F/((2*a-1)*Er*576); gen=K0*tau/576*L
    print(f"K0={K0} tau={tau}: (b) allows net notional/round {allowed*100:.3f}%T ; K0,tau generate {gen*100:.3f}%T (ratio {allowed/gen:.2f}) ; today's limit 5.219T")
# nonlinear: balanced book, BTC L=240 (cap/5 tier) r = stress
stress=.00817; L=240; E=0.0025*1e8/stress
S=E/L  # stake each side
r=stress
win=min(L*r,19)*S; lose=min(L*r,1)*S  # fraction: loser loses stake at most
print("balanced book U=D=E, L=240, r=stress: treasury loses %.1f PLAY = %.3f%% of T=1e8 (linear model says 0)"%(win-lose,(win-lose)/1e8*100))
# same with each side 100*E (net lambda=1 rule would allow gross 100E when b tiny)
print("same with U=D=100E: %.1f%% of T"%((win-lose)*100/1e8*100))
# L=1200 (stake<=250) 
L=1200; S=E/L; win=min(L*r,19)*S; lose=min(L*r,1)*S
print("L=1200 (stake<=250, cap BTC) balanced U=D=E: loss %.2f%% T"%((win-lose)/1e8*100))
# T dependence of K0 threshold
T0=1e8; E=0.0025*T0/stress; w=.2;p=.6;L=10
k=E/(L*w*p); print("K0 threshold T=1e8: %.1fM"%(k/1e6))
# with T=1e8-K0:
K=k
for _ in range(50): K=0.0025*(T0-K)/stress/(L*w*p)
print("K0 threshold with T=T0-K0: %.1fM"%(K/1e6))
# RTP at q=100: min stake 1 PLAY x2 BTC; fee_net 0.001; herd fee ceil .001
for S,Lv in [(1,2),(10,10),(10,240)]:
    herd=math.ceil(S*min(.01,0.92e-4*Lv)*1000-1e-9)/1000; herd=max(herd,.001); tot=herd+0.001
    ideal=S*min(.01,0.92e-4*Lv)+0.001
    print(f"q=100 stake {S} x{Lv}: herd {herd} total {tot} = {tot/S*100:.3f}% ; unrounded {ideal/S*100:.3f}%")
# 1M players table
N=1e6
for q,issue in [(1,1e8),(100,1e8),(1,1e12),(100,1e10),(1e4,1e8)]:
    pack=10000/q; K0=N*pack
    print(f"q={q:g} issue={issue:.0e}: pack {pack:g}, K0={K0:.2e} = {K0/issue*100:.1f}% of issue; min stake {100/q:g}, net fee {0.1/q:g}; Ville P(DD>=10%) <= {K0/(K0+0.1*issue):.3f}")
